import br.com.pelotavision.*;import org.opencv.core.*;import org.opencv.imgcodecs.Imgcodecs;import org.opencv.imgproc.Imgproc;import java.nio.file.*;
class OldSelect {public static void main(String[] args)throws Exception{nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);Mat original=Imgcodecs.imread(args[0],0);Path out=Path.of(args[1]);Files.createDirectories(out);for(int size:new int[]{1536,600}){Mat gray=new Mat();Imgproc.resize(original,gray,new Size(size,Math.round(original.rows()*size/(double)original.cols())),0,0,Imgproc.INTER_AREA);DetectionTuner.Report report=DetectionTuner.search(gray,new DetectionTuner.Option(3,75,false),new DetectionAssessment.Context(null,gray.cols(),gray.rows(),null,5),()->false,(a,b,c)->{});DetectionTuner.Trial best=report.best();Diagnose.save(best.result,best.option,out.resolve("old_auto_"+size+".json"));System.out.println(size+" old auto "+best.option.id+" count="+best.metrics.total+" valid="+best.metrics.valid);gray.release();}original.release();}}
